60	// ------------------------------------------------------------
61	// Read Buffer
62	// ------------------------------------------------------------
63	
64	void read_buffer(TT_DATA mem[NITER][memSizeAct],
65	                 TT_SAMPLE (&buff)[NITER][NSTREAM_INT][(memSizeAct * samplesPerRead) / NSTREAM_INT]) {
66	    for (int nn = 0; nn < NITER; nn++) {
67	        for (int rr = 0, mm = 0, ss0 = 0, addr0 = 0; rr < memSizeAct; rr++) {
68	#pragma HLS PIPELINE II = 1
69	            if (samplesPerRead == 2) {
70	                int ss1 = (ss0 == NSTREAM_INT - 1) ? 0 : ss0 + 1;
71	                int addr1 = (ss0 == NSTREAM_INT - 1) ? addr0 + 1 : addr0;
72	                TT_SAMPLE val0 = buff[nn][ss0][addr0];
73	                TT_SAMPLE val1 = buff[nn][ss1][addr1];
74	                if (ss0 == NSTREAM_INT - 1 || ss1 == NSTREAM_INT - 1) {
75	                    addr0 += 1;
76	                }
77	                mem[nn][mm++] = (val1, val0);
78	            } else {
79	                int ss1 = (ss0 == NSTREAM_INT - 1) ? 0 : ss0 + 1;
80	                int ss2 = (ss0 >= NSTREAM_INT - 2) ? ss0 + 2 - NSTREAM_INT : ss0 + 2;
81	                int ss3 = (ss0 >= NSTREAM_INT - 3) ? ss0 + 3 - NSTREAM_INT : ss0 + 3;
82	                int addr1 = (ss0 == NSTREAM_INT - 1) ? addr0 + 1 : addr0;
83	                int addr2 = (ss0 >= NSTREAM_INT - 2) ? addr0 + 1 : addr0;
84	                int addr3 = (ss0 >= NSTREAM_INT - 3) ? addr0 + 1 : addr0;
85	                TT_SAMPLE val0 = buff[nn][ss0][addr0];
86	                TT_SAMPLE val1 = buff[nn][ss1][addr1];
87	                TT_SAMPLE val2 = buff[nn][ss2][addr2];
88	                TT_SAMPLE val3 = buff[nn][ss3][addr3];
89	                // printf("reading [%d,%d] from %d %d %d\n", val0>>16, val0 % (1<<15), nn, ss0, addr0);
90	                // printf("reading [%d,%d] from %d %d %d\n", val1>>16, val1 % (1<<15), nn, ss1, addr1);
91	                // printf("reading [%d,%d] from %d %d %d\n", val2>>16, val2 % (1<<15), nn, ss2, addr2);
92	                // printf("reading [%d,%d] from %d %d %d\n", val3>>16, val3 % (1<<15), nn, ss3, addr3);
93	                if (ss0 == NSTREAM_INT - 1 || ss1 == NSTREAM_INT - 1 || ss2 == NSTREAM_INT - 1 ||
94	                    ss3 == NSTREAM_INT - 1) {
95	                    addr0 += 1;
96	                }
97	                mem[nn][mm++] = (val3, val2, val1, val0);
98	            }
99	            ss0 = (ss0 + samplesPerRead > NSTREAM_INT - 1) ? ss0 + samplesPerRead - NSTREAM_INT : ss0 + samplesPerRead;
100	        }
101	    }
102	}
